const rowStyle = { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' as const };
function NumberField({ label, value, onChange, min, max, disabled = false }: { label: string; value: number; onChange: (n: number) => void; min?: number; max?: number; disabled?: boolean }) {
  const {t}=useI18n();
  return <label>{t(label)}<input aria-label={t(label)} type="number" step="any" value={Object.is(value,-0)?'-0':value} min={min} max={max} disabled={disabled} style={{ width: 75 }} onChange={e => { if (e.target.value === '') return; const n = Number(e.target.value); if (Number.isFinite(n) && (min === undefined || n >= min) && (max === undefined || n <= max)) onChange(n); }} /></label>;
}
function TargetSelect({label,value,targets,onChange}:{label:string;value:string;targets:readonly string[];onChange:(value:string)=>void}){
 const {t}=useI18n();return <select aria-label={t(label)} value={value} onChange={event=>onChange(event.target.value)}>{animationTargetChoices(targets,value).map(choice=><option key={choice.value} value={choice.value} disabled={choice.retained}>{choice.retained?t('{target}（保留）',{target:choice.value}):choice.value==='*'?t('所有参数'):choice.value}</option>)}</select>;
}
function ParameterEditor({ values, targets, scene, onChange }: { values: ParameterAnimation[]; targets: string[]; scene: SceneDocument; onChange: (v: ParameterAnimation[]) => void }) {
  const {t}=useI18n();
  const [error,setError]=useState('');
  const patch = (index: number, next: Partial<ParameterAnimation>) => onChange(values.map((v, i) => i === index ? { ...v, ...next } : v));
  return <div style={{ display: 'grid', gap: 7, width: '100%' }}>{values.map((v, i) => <div key={i} style={rowStyle}>
    <TargetSelect label={t("振荡目标 {0}",{0:i + 1})} value={v.target} targets={targets} onChange={target => patch(i, { target,binding:undefined })} />
    <NumberField label={t("最小值 {0}",{0:i + 1})} value={v.min} onChange={min => patch(i, { min })} /><NumberField label={t("最大值 {0}",{0:i + 1})} value={v.max} onChange={max => patch(i, { max })} />
    <NumberField label={t(v.model==='domain-1.7.8'?"每帧步长（60 fps 参考）{0}":"相位速度 rad/s {0}",{0:i + 1})} value={v.step} onChange={step => patch(i, { step })} />
    {v.model==='domain-1.7.8'&&<span className="muted">{t('端点原值保留，计算时排序；步长符号决定起始方向。')}</span>}
    <label><input type="checkbox" checked={!!v.edgeEasing} onChange={event=>patch(i,{edgeEasing:event.target.checked?{...DEFAULT_EDGE_EASING}:undefined})} />{t('端点减速')}</label>
    {v.edgeEasing&&<><NumberField label={t("端点窗口 rad")} min={.000001} value={v.edgeEasing.window} onChange={window=>patch(i,{edgeEasing:{...v.edgeEasing!,window}})} /><NumberField label={t("最低速度比例")} min={0} max={1} value={v.edgeEasing.floor} onChange={floor=>patch(i,{edgeEasing:{...v.edgeEasing!,floor}})} /><label>{t('端点缓动')}<select aria-label={t("端点缓动")} value={v.edgeEasing.easing} onChange={event=>patch(i,{edgeEasing:{...v.edgeEasing!,easing:event.target.value}})}>{EASING_NAMES.map(name=><option key={name}>{name}</option>)}</select></label></>}
    {complexCompanion(scene,v.target)&&<label><input type="checkbox" checked={!!v.binding} onChange={event=>patch(i,{binding:event.target.checked?{mode:'complex-full',imaginaryTarget:complexCompanion(scene,v.target)!}:undefined})} />{t('锁定启动时虚部')}</label>}
    <label><input type="checkbox" checked={v.enabled} onChange={e => patch(i, { enabled: e.target.checked })} />{t("启用")}</label>
    <button title={t("删除参数振荡")} onClick={() => onChange(values.filter((_, j) => j !== i))}><X size={13} /></button>
  </div>)}{error&&<p role="alert" className="error">{t(error)}</p>}{!bouncingExperience(scene).continuous&&<button className="text-button" style={{ justifySelf: 'start' }} onClick={() => { try { const target = targets[0] ?? gradientAnimationCapabilities(scene).paletteOffsetTarget, value = readAnimationValue(scene, target); onChange([...values, { target, ...(parameterAnimationSuggestion(scene,target)??{min:value-1,max:value+1}), step: 1, enabled: true }]); setError(''); } catch(error) {setError(error instanceof Error?error.message:String(error));} }}><Plus size={13} />{t("添加参数")}</button>}</div>;
}
function GradientEditor({ config, scene, onChange }: { config?: GradientAnimation; scene: SceneDocument; onChange: (v: GradientAnimation) => void }) {
  const {t}=useI18n();
  const g:GradientAnimation = config ?? { mode: 'offset_cycle', speed: .1, interpolation: 'rgb' };
  const patch = (v: Partial<GradientAnimation>) => onChange({ ...g, ...v });
  const capabilities=gradientAnimationCapabilities(scene);
  const stopBased = capabilities.localPalette&&(scene.palette.mode === 'linear' || scene.palette.mode === 'sine');
  const offsets=g.model==='offsets',domainOffsets=offsets&&scene.kind==='domain';
  const supported = offsets?capabilities.offsets:capabilities.localPalette&&(stopBased||g.mode==='offset_cycle');
  const morph = !offsets&&supported && (g.mode === 'palette_morph' || g.mode === 'cross_fade');
  return <div style={{ display: 'grid', gap: 8, width: '100%' }}><div style={rowStyle}>
    {(capabilities.offsets||offsets)&&<label>{t('渐变类型')}<select aria-label={t('渐变类型')} value={g.model??'palette'} onChange={e=>patch({model:e.target.value as GradientAnimation['model'],speed:e.target.value==='offsets'?Math.abs(g.speed)*360:g.speed/360})}><option value="palette" disabled={!capabilities.localPalette}>{t('色板动画')}</option><option value="offsets" disabled={!capabilities.offsets}>{t(scene.kind==='domain'?'域偏移与循环采样':'内部与外部偏移')}</option></select></label>}
    <label>{t("渐变方式")}<select aria-label={t("渐变方式")} disabled={!supported} value={g.mode} onChange={e => patch({ mode: e.target.value as GradientAnimation['mode'] })}><option value="offset_cycle">{t("偏移循环")}</option><option disabled={!offsets&&!stopBased} value="hue_rotate">{t("色相旋转")}</option><option disabled={!offsets&&!stopBased} value="palette_morph">{t("调色板往返变形")}</option><option disabled={!offsets&&!stopBased} value="cross_fade">{t("渐变交叉淡化")}</option></select></label>
    <NumberField label={t(offsets?'渐变速度 °/s':"渐变速度 /s")} value={g.speed} min={offsets?0:undefined} disabled={!supported} onChange={speed => patch({ speed })} />
    {(morph||offsets) && <label>{t(domainOffsets?'相位曲线与循环颜色插值':offsets?'偏移相位曲线':"颜色插值")}<select aria-label={t(domainOffsets?'相位曲线与循环颜色插值':offsets?'偏移相位曲线':"颜色插值")} value={g.interpolation} onChange={e => patch({ interpolation: e.target.value as GradientAnimation['interpolation'] })}>{['rgb', 'linear', 'oklab', 'oklch'].map(space => <option key={space}>{space}</option>)}</select></label>}
    {offsets&&<>{(['affectInside','affectOutside'] as const).map(key=><label key={key}><input type="checkbox" aria-label={t(key==='affectInside'?'影响内部':'影响外部')} checked={g[key]??true} onChange={e=>patch({[key]:e.target.checked})}/>{t(key==='affectInside'?'影响内部':'影响外部')}</label>)}</>}
  </div>{!offsets&&capabilities.retainedPaletteWarning&&<p role="status" className="muted">{t(capabilities.retainedPaletteWarning)}</p>}{domainOffsets?<><p className="muted">{t('域着色仅有一个偏移。偏移循环不移动它；其余模式仅同时启用内部和外部时移动。运行时使用循环色标，停止后恢复普通采样。')}</p>{capabilities.localPalette&&<p className="muted">{t('函数、HSV 或带位置色板保留自身采样，仅应用域偏移；循环颜色插值用于无位置的线性色标。')}</p>}</>:offsets&&<p className="muted">{t('偏移动画保留色板形状，可用于余弦与曲线色板；固定颜色区域不随偏移变化。')}</p>}{!offsets&&capabilities.localPalette&&!stopBased && <p className="muted" style={{ margin: 0 }}>{t("当前函数色图可做偏移循环；色标动画需要在外观中选择线性或正弦渐变。")}</p>}{morph && (['fromStops', 'toStops'] as const).map(key => {
    const stops = g[key] ?? (key === 'fromStops' ? scene.palette.stops : [...scene.palette.stops].reverse());
    return <div key={key} style={rowStyle}><span>{key === 'fromStops' ? t("起始颜色") : t("目标颜色")}</span>{stops.map((color, i) => <span key={i} style={{ display: 'inline-flex' }}><input aria-label={`${key} ${i + 1}`} type="color" value={color} onChange={e => patch({ [key]: stops.map((c, j) => i === j ? e.target.value : c) })} />{stops.length > 2 && <button aria-label={t("删除色标 {0} {1}",{0:key,1:i + 1})} onClick={() => patch({ [key]: stops.filter((_, j) => j !== i) })}><X size={10} /></button>}</span>)}{stops.length < 32 && <button title={t("添加色标")} onClick={() => patch({ [key]: [...stops, stops[stops.length - 1]] })}><Plus size={12} /></button>}</div>;
  })}</div>;
}
/** Roots uses one scalar offset; these phase-shaping choices do not edit LUT stops. */
type SourceGradientEditorProps={config?:GradientAnimation;onChange:(value:GradientAnimation)=>void};
export function RootsGradientEditor(props:SourceGradientEditorProps){return <SourceGradientEditor {...props} family="roots"/>;}
export function SurfaceGradientEditor(props:SourceGradientEditorProps){return <SourceGradientEditor {...props} family="surface"/>;}
export function AttractorGradientEditor(props:SourceGradientEditorProps){return <SourceGradientEditor {...props} family="attractor"/>;}
export function PerlinGradientEditor(props:SourceGradientEditorProps){return <SourceGradientEditor {...props} family="perlin"/>;}
function SourceGradientEditor({config,onChange,family}:SourceGradientEditorProps&{family:'roots'|'surface'|'attractor'|'perlin'}){
 const {t}=useI18n(),particle=family!=='roots',perlin=family==='perlin',attractor=family==='attractor';let parsed:RootsGradientConfiguration|undefined,error='';
 try{if(config!==undefined)parsed=particle?parseSourceParticleGradientConfiguration(config):parseRootsGradientConfiguration(config);}catch(reason){error=reason instanceof Error?reason.message:String(reason);}
 const create=(value:RootsGradientConfiguration):GradientAnimation=>({...value,model:'offsets',affectInside:true,affectOutside:true});
 if(!parsed)return <div data-testid={`${family}-gradient-unconfigured`}><p role="status">{t('保留的渐变动作尚无有效源配置，需要明确设置后才执行。')}</p>{error&&<p role="alert">{t(error)}</p>}<button onClick={()=>onChange(create(particle?SOURCE_PARTICLE_GRADIENT_DEFAULT:ROOTS_GRADIENT_DEFAULT))}>{t('设置源渐变配置')}</button></div>;
 const g=parsed,patch=(value:Partial<RootsGradientConfiguration>)=>onChange(create({...g,...value}));
 const modeLabels:Record<RootsGradientConfiguration['mode'],string>={hue_rotate:'色相旋转',offset_cycle:'偏移循环',palette_morph:'调色板往返变形',cross_fade:'渐变交叉淡化'};
 return <div style={{display:'grid',gap:8,width:'100%'}} data-testid={`${family}-gradient-config`}><div style={rowStyle}>
  <label>{t('渐变方式')}<select aria-label={t('渐变方式')} value={g.mode} onChange={event=>patch({mode:event.target.value as RootsGradientConfiguration['mode']})}>{(particle?SOURCE_PARTICLE_GRADIENT_MODES:ROOTS_GRADIENT_MODES).map(mode=><option key={mode} value={mode}>{t(modeLabels[mode])}</option>)}</select></label>
  <NumberField label={t('渐变速度 °/s')} value={g.speed} min={0} onChange={speed=>patch({speed})}/>
  <label>{t(perlin||attractor?'相位与颜色插值':particle?'相位曲线与循环颜色插值':'偏移相位曲线')}<select aria-label={t(perlin||attractor?'相位与颜色插值':particle?'相位曲线与循环颜色插值':'偏移相位曲线')} value={g.interpolation} onChange={event=>patch({interpolation:event.target.value as RootsGradientConfiguration['interpolation']})}>{(particle?SOURCE_PARTICLE_GRADIENT_INTERPOLATIONS:ROOTS_GRADIENT_INTERPOLATIONS).map(mode=><option key={mode} value={mode}>{mode}</option>)}</select></label>
 </div><p className="muted">{t(perlin?'渐变更新纹理色板，停止保留最后偏移。同一片段仅执行列表中最后一个有效渐变动作。':attractor?'显示拖尾时更新点与拖尾颜色；停止保留最后偏移。同片段渐变动作按列表顺序执行。':particle?'渐变同时作用于曲面两侧；运行时循环采样色板并按记录年龄着色拖尾。停止保留最后的色板偏移；同片段动作按列表顺序执行。':'这些模式与相位曲线更新同一个源色板偏移，不替换色标。停止动作保留最后偏移；同片段渐变动作按列表顺序执行。')}</p></div>;
}
